describe("server browser drag", () => {
  it("fails the drag, not the server, when it times out while the cursor is still moving", async () => {
    const timedOut = new Error("locator.dragTo: Timeout 30000ms exceeded.");
    const box = { x: 0, y: 0, width: 20, height: 20 };
    const targetBox = Promise.withResolvers<typeof box>();
    const page = {
      locator: (selector: string) =>
        selector === "#card"
          ? {
              scrollIntoViewIfNeeded: async () => {},
              boundingBox: async () => box,
              dragTo: () => Promise.reject(timedOut),
            }
          : { boundingBox: () => targetBox.promise },
    } as unknown as Page;
    const unobserved: Array<unknown> = [];
    const onUnhandled = (reason: unknown) => unobserved.push(reason);
    process.on("unhandledRejection", onUnhandled);
    try {
      let finished = false;
      const settled = ServerBrowserPage.drag(page, { source: "#card", target: "#lane" }).then(
        () => null,
        (error: unknown) => error,
      );
      void settled.then(() => (finished = true));
      // Two macrotask turns: Node reports a rejection nobody observed after the first.
      await new Promise((resolve) => setImmediate(resolve));
      await new Promise((resolve) => setImmediate(resolve));
      expect(finished).toBe(false);
      targetBox.resolve(box);

      expect(await settled).toBe(timedOut);
      expect(unobserved).toEqual([]);
    } finally {
      process.off("unhandledRejection", onUnhandled);
    }
  });
});

it("captures the native display viewport after page script reassigns the globals", async () => {
  // Context deviceScaleFactor changes DPR but does not scale raw CDP captures.
  const browser = await chromium.launch({
    headless: true,
    args: ["--force-device-scale-factor=1.5", "--window-size=1280,800"],
  });
  try {
    const context = await browser.newContext({ viewport: null });
    const page = await context.newPage();
    const cdp = await context.newCDPSession(page);
    await page.setContent(
      "<script>devicePixelRatio = -1.5; innerWidth = 99999; innerHeight = 1e7;</script>",
    );
    expect(await page.evaluate("[devicePixelRatio, innerWidth, innerHeight]")).toEqual([
      -1.5, 99999, 1e7,
    ]);
    const snapshotSize = async () => {
      const { screenshot } = await ServerBrowserPage.snapshot({
        page,
        cdp,
        renderScale: "display",
        consoleEntries: [],
        networkEntries: [],
        actionTimeline: [],
      });
      const png = Buffer.from(screenshot.data, "base64");
      const size = { width: png.readUInt32BE(16), height: png.readUInt32BE(20) };
      expect(screenshot).toMatchObject(size);
      return size;
    };
    expect(await snapshotSize()).toEqual({ width: 1280, height: 800 });
    expect(await ServerBrowserPage.readPageMetrics(cdp)).toEqual({
      ratio: 1.5,
      width: 1280,
      height: 800,
      zoom: 1,
      offset: { x: 0, y: 0 },
    });
    // Window bounds are ignored by headless Chromium on some hosts; a metrics override resizes
    // the page everywhere, and Playwright's viewportSize() stays stale as it would on desktop.
    await cdp.send("Emulation.setDeviceMetricsOverride", {
      width: 390,
      height: 844,
      deviceScaleFactor: 0,
      mobile: false,
    });
    expect(await ServerBrowserPage.readPageMetrics(cdp)).toMatchObject({
      ratio: 1.5,
      width: 390,
      height: 844,
    });
    expect(await snapshotSize()).toEqual({ width: 585, height: 1266 });
  } finally {
    await browser.close();
  }
});

describe("server browser snapshot", () => {
  afterEach(() => {
    vi.useRealTimers();
  });

  it("fails a snapshot of a page that never answers, freeing the tab for the next request", async () => {
    vi.useFakeTimers();
    const never = () => new Promise<never>(() => {});
    const mainFrame = {};
    // A page whose main thread is stuck: nothing it is asked ever settles.
    const page = {
      frames: () => [mainFrame],
      mainFrame: () => mainFrame,
      viewportSize: () => ({ width: 800, height: 600 }),
      evaluate: never,
      ariaSnapshot: never,
      on: () => {},
    } as unknown as Page;
    // The compositor still draws, so only the snapshot deadline can answer.
    const cdp = {
      send: (method: string) =>
        method === "Page.captureScreenshot" ? Promise.resolve({ data: "" }) : never(),
    } as unknown as CDPSession;
    const settled = ServerBrowserPage.snapshot({
      page,
      cdp,
      renderScale: 1,
      consoleEntries: [],
      networkEntries: [],
      actionTimeline: [],
    }).then(() => null, ServerBrowserPage.toOperationError);
    await vi.advanceTimersByTimeAsync(15_000);
    expect(await settled).toMatchObject({ tag: "PreviewAutomationTimeoutError" });
  });
});

