import {
  chromium,
  type Browser,
  type BrowserContext,
  type CDPSession,
  type Page,
} from "playwright-core";
import {
  afterAll,
  afterEach,
  beforeAll,
  beforeEach,
  describe,
  expect,
  it,
  vi,
} from "vite-plus/test";

import { presentAsChrome } from "./ServerBrowserContexts.ts";
import * as ServerBrowserPage from "./ServerBrowserPage.ts";

describe("server browser element refs", () => {
  let browser: Browser;
  let context: BrowserContext;
  let page: Page;
  let cdp: CDPSession;

  beforeAll(async () => {
    browser = await chromium.launch({ headless: true });
  });
  afterAll(async () => {
    await browser?.close();
  });
  beforeEach(async () => {
    context = await browser.newContext();
    page = await context.newPage();
    cdp = await context.newCDPSession(page);
  });
  afterEach(async () => {
    await context.close();
  });

  const takeSnapshot = () =>
    ServerBrowserPage.snapshot({
      page,
      cdp,
      renderScale: 1,
      consoleEntries: [],
      networkEntries: [],
      actionTimeline: [],
    });
  const locators = (tree: unknown) => {
    expect(typeof tree).toBe("string");
    return Array.from(
      String(tree).matchAll(/\[ref=([^\]]+)\]/g),
      (match) => `aria-ref=${match[1]}`,
    );
  };
  const buttonLocator = (tree: unknown, name: string) => {
    const line = String(tree)
      .split("\n")
      .find((line) => line.includes(`button "${name}"`));
    const locator = locators(line)[0];
    expect(locator).toBeDefined();
    return locator!;
  };
  const repeatedRows = `<ul>${Array.from({ length: 5 }, (_, i) => `<li>row ${i + 1}<button data-testid="delete-row" onclick="this.parentElement.remove()">delete</button></li>`).join("")}</ul>`;

  it("gives up on a screenshot when the page draws no frame", async () => {
    // A desktop tab whose thread is not open never answers a capture.
    let captures = 0;
    const captureStarted = Promise.withResolvers<void>();
    const stuck = {
      send: (method: string, params?: object) => {
        if (method !== "Page.captureScreenshot")
          return cdp.send(method as "Page.getLayoutMetrics", params);
        captures += 1;
        captureStarted.resolve();
        return new Promise(() => {});
      },
    } as unknown as CDPSession;
    const snapshotOf = () =>
      ServerBrowserPage.snapshot({
        page,
        cdp: stuck,
        renderScale: 1,
        consoleEntries: [],
        networkEntries: [],
        actionTimeline: [],
      });
    vi.useFakeTimers({ toFake: ["setTimeout", "clearTimeout"] });
    try {
      const rejected = expect(snapshotOf()).rejects.toThrow("did not draw a frame");
      // The capture's limit starts only after the snapshot's real CDP reads.
      await captureStarted.promise;
      await vi.advanceTimersByTimeAsync(5_000);
      await rejected;
      // Chromium still holds the first capture, so a retry fails without starting another.
      await expect(snapshotOf()).rejects.toThrow("did not draw a frame");
      expect(captures).toBe(1);
    } finally {
      vi.useRealTimers();
    }
