        tabIndex={0}
        role="application"
        aria-label={`${props.deviceId === "iphone-x" ? "iPhone X" : props.platform === "ios" ? "iOS Simulator" : "Android Emulator"} screen`}
        onBlur={() => {
          if (client?.cancelTouch) {
