    updates: ReadonlyArray<WatchUpdate>,
  ): Effect.Effect<ReadonlyArray<WatchUpdate>> =>
    send(updates).pipe(
      Effect.andThen(Effect.forEach(updates, (update) => landed(update, true))),
      Effect.as<ReadonlyArray<WatchUpdate>>([]),
