      Effect.all(
        [
          pullRequests.detail({ ...reference, allowStale: false }),
          plan.activity
            ? pullRequests.activity(reference).pipe(Effect.map(Option.some))
            : Effect.succeed(Option.none<PullRequestActivity>()),
