  // Each prefix consumes its trailing whitespace once to avoid nested-prefix backtracking.
  for (const block of markdown.matchAll(
    /^[ \t]*(?:>[ \t]+|(?:[-*+]|\d+[.)])[ \t]+(?:\[[ x]\][ \t]+)?)*(`{3,})[^`\n]*\n[\s\S]*?(?:^[ \t]*(?:>[ \t]*)*\1`*[ \t]*(?=\n|$)|(?![\s\S]))/gm,
