      group: group.key,
      next: null,
      news: {
        repository: target.link.repository,
        number: target.link.number,
        text: `Pull request #${target.link.number} (${target.link.url}) was closed, so T3 Code stopped watching it. Call watch_pull_request if it reopens.`,
