        if (isInteractive) return;

        setIsComposerScrollCollapsed(false);
        if (isComposerResting && !target.closest('[data-testid="composer-editor"]')) {
          event.preventDefault();
          setIsComposerFocused(true);
          scheduleComposerFocus();
