    if (currentAttempt !== undefined) {
      yield* emitEvent({
        type: "run-attempt.updated",
        threadId: input.command.threadId,
        runId: targetRun.id,
        nodeId: rootNodeId,
        providerInstanceId: targetRun.providerInstanceId,
        occurredAt: now,
        payload: { ...currentAttempt, status: "superseded", completedAt: now },
