      if (commandAdvertisementDelayMs >= 0) {
        yield* Effect.sleep(`${commandAdvertisementDelayMs} millis`).pipe(
          Effect.andThen(
            agent.client.sessionUpdate({
              sessionId,
              update: {
                sessionUpdate: "available_commands_update",
