            title: process.env.T3_ACP_PERMISSION_TITLE ?? `\`${command}\``,
            subject: {
              type: "tool_call",
              toolCall: {
                toolCallId: index === 0 ? toolCallId : `${toolCallId}-${index + 1}`,
                title: process.env.T3_ACP_PERMISSION_TITLE ?? `\`${command}\``,
                kind: "execute",
                status: "pending",
                rawInput: {
                  variant: "Bash",
                  command,
