      const { ratio, width, height } = result.value as {
        readonly ratio: number;
        readonly width: number;
        readonly height: number;
      };
      return {
        ratio,
        width,
        height,
        zoom,
        offset: { x: cssVisualViewport.pageX * zoom, y: cssVisualViewport.pageY * zoom },
      };
