      ...offset,
      ...viewport,
      scale: options.scale,
    };
  }
  const { data } = await cdp.send("Page.captureScreenshot", {
    format: options.format,
    ...(options.quality === undefined ? {} : { quality: options.quality }),
    ...(clip ? { clip } : {}),
