    return Promise.all([
      ...keys.map(({ key, code }) =>
        session.send("Input.dispatchKeyEvent", { type: "keyUp", key, code }).catch(constVoid),
      ),
      ...buttons.map(([button, point]) =>
        session
          .send("Input.dispatchMouseEvent", {
            type: "mouseReleased",
            button,
            ...point,
            buttons: 0,
            clickCount: 1,
          })
          .catch(constVoid),
      ),
    ]).then(constVoid);
  };

