      const target = resolvePersonalUpdateTargetVersion(null, current, feed);
      const servers = collectPublishedPersonalServerUpdateTargets(
        [
          machine("service", current, "boot-service"),
          machine("managed-vps", current, "respawn"),
          machine("other-desktop", current, "desktop-managed"),
          machine("local-wsl", current, "desktop-managed", { hostedByThisApp: true }),
          machine("stable-service", "0.0.45", "boot-service"),
          machine("manual-npm", current, undefined),
