        target,
        feed,
      );
      expect(servers.map((server) => server.serverLabel)).toEqual([
        "service",
        "managed-vps",
        "other-desktop",
      ]);
      expect(servers.every((server) => server.targetVersion === published)).toBe(true);
    },
  );

  it("does not offer unpublished server archives while desktop targets keep their own feed", () => {
    const machines = [
      machine("service", current, "boot-service"),
      machine("managed-vps", current, "respawn"),
      machine("other-desktop", current, "desktop-managed"),
    ];
    for (const feed of [null, { ...status, releasedVersion: null }, status]) {
      expect(
        collectPublishedPersonalServerUpdateTargets(
          machines,
          "0.0.46-nightly.20261012.300",
          feed,
        ).map((server) => server.serverLabel),
      ).toEqual(["other-desktop"]);
