      while (!before.downloads?.length) {
        yield* Effect.yieldNow;
        before = yield* status();
      }
      yield* broker.invoke({ scope, tabId, operation: "recordingStart", input: {} });
      const encoder = scratchPages[0]!;
      const attached = Promise.withResolvers<void>();
