      if (method === "Page.captureScreenshot") return { data: "ZnJhbWU=" };
      if (method === "Page.getFrameTree") return { frameTree: { frame: { id: "main" } } };
      if (method === "Page.createIsolatedWorld") return { executionContextId: 7 };
