/** Reads and disarms a paste-as-text deadline: the shortcut applies to one paste only. */
function consumePasteAsTextShortcut(deadline: { current: number }): boolean {
  const armed = Date.now() <= deadline.current;
  deadline.current = 0;
  return armed;
}

